// util.types on values of each kind and their look-alikes: subclasses, proxies, a revoked
// proxy, a forged tag, a swapped prototype. The same package under Node.js prints the same.
module.exports = function () {
  const t = require("util").types;
  class M extends Map { get [Symbol.toStringTag]() { return "X"; } }
  const revoked = Proxy.revocable({}, {}); revoked.revoke();
  const fakeMap = { [Symbol.toStringTag]: "Map" };
  const abProtoSwap = new ArrayBuffer(1); Object.setPrototypeOf(abProtoSwap, SharedArrayBuffer.prototype);
  const values = { ab: new ArrayBuffer(4), sab: new SharedArrayBuffer(4), u8: new Uint8Array(2), dv: new DataView(new ArrayBuffer(2)), map: new Map(), sub: new M(), set: new Set(), date: new Date(0), re: /x/, num: Object(1), str: Object("s"), big: Object(1n), sym: Object(Symbol()), wm: new WeakMap(), ws: new WeakSet(), obj: {}, fakeMap, proxyMap: new Proxy(new Map(), {}), revoked: revoked.proxy, abProtoSwap, fn() {} , n: 5 };
  const checks = ["isArrayBuffer", "isSharedArrayBuffer", "isAnyArrayBuffer", "isDataView", "isMap", "isSet", "isDate", "isRegExp", "isNumberObject", "isStringObject", "isBigIntObject", "isSymbolObject", "isBoxedPrimitive", "isWeakMap", "isWeakSet", "isArrayBufferView", "isUint8Array"];
  for (const [name, v] of Object.entries(values)) console.log(name.padEnd(12), checks.map((c) => (t[c](v) ? 1 : 0)).join(""));
};
